import { CallStatus } from '@/types/api.types';
import { useProfilesStore } from '@/store';
import { ApiGlobalStateManager } from '@/lib/api-state';
import { ProfileServices } from '@/api';
import { IsTokenValid } from '@/utils/token';

// `GET /profile/me` is needed by the sidebar, the digital-ID column and several
// pages at once. Without coordination every one of them fires its own request on
// first paint. This keeps a single in-flight promise so concurrent callers share
// one network call, and later callers reuse the value already in the store.
let inFlight: Promise<void> | null = null;

/**
 * Load the signed-in user's profile into the shared store exactly once.
 * Concurrent callers await the same request; once loaded it resolves immediately.
 * Pass `force` after a mutation to refresh the cached value.
 */
export const ensureMyProfileLoaded = (force = false): Promise<void> => {
    if (!IsTokenValid()) return Promise.resolve();

    const { profileState, setProfileState } = useProfilesStore.getState();

    if (!force && profileState.status === CallStatus.Success && profileState.data?.id) {
        return Promise.resolve();
    }
    if (inFlight && !force) return inFlight;

    inFlight = ApiGlobalStateManager(ProfileServices.GetProfile(), setProfileState)
        .finally(() => { inFlight = null; });

    return inFlight;
};

/** Drop the cached in-flight request (used when auth state is reset). */
export const resetMyProfileCache = (): void => { inFlight = null; };
